  "effective_date": {
    "value": ["2024-01-01"],
    "status": "present",
    "citation": "1. Document Control"
  },
  "purpose": {
    "value": ["This procedure standardizes intake of customer card-dispute notices before an investigator reviews them."],
    "status": "present",
    "citation": "2. Purpose"
  },
  "required_steps": {
    "value": ["Record the merchant, amount, posting date, customer recognition statement, and available receipt. Create a review item and route it to Card Disputes. Do not promise reimbursement."],
    "status": "present",
    "citation": "3. Required Steps"
  },
  "exceptions": {
    "value": ["If the customer also reports unrecognized transactions, pause ordinary intake and escalate for possible fraud review."],
    "status": "present",
    "citation": "4. Exceptions"
  }
}

 {
